style.css:
/* Deshabilitar y ocultar el botón usando el atributo aria-label */
button[aria-label="Estados"] {
    display: none !important;  /* Oculta el botón completamente */
    visibility: hidden !important;  /* Asegura que el botón no sea visible */
    pointer-events: none !important;  /* Bloquea interacciones con el botón */
    opacity: 0 !important;  /* Hace que el botón sea completamente transparente */
    position: absolute !important;  /* Saca el botón del flujo normal del documento */
    top: -9999px !important;  /* Mueve el botón fuera de la vista */
    left: -9999px !important;  /* Mueve el botón fuera de la vista */
}
